import { defineConfig } from 'astro/config';

// Vocele marketing site — static output only (no server runtime, no SSR/hydration
// complexity). Every route is plain, pre-rendered HTML at build time: fastest possible
// path for Google + AI crawlers (Perplexity, ChatGPT browsing, Google AI Overviews) to
// read full content with zero JS execution required.
//
// Note: deliberately NOT using @astrojs/sitemap — it crashed at build time with this
// Astro version (an internal route-API mismatch between astro@4.16 and
// @astrojs/sitemap@3.7). sitemap.xml is generated by src/pages/sitemap.xml.ts from the
// route manifest in src/site-pages.ts — same source that drives the <head> hreflang, so
// the two can't drift, and it can never break on a future upgrade.
export default defineConfig({
  // Build-time origin; overridable via PUBLIC_SITE_URL (Dockerfile ARG) for staging.
  site: process.env.PUBLIC_SITE_URL || 'https://vocele.app',
  output: 'static',
  trailingSlash: 'never',
  i18n: {
    locales: ['en', 'es'],
    defaultLocale: 'en',
    routing: {
      prefixDefaultLocale: false, // English stays at /, /pricing, /faq (default + broad,
                                   // mirrors the en-US App Store listing strategy)
    },
  },
  build: {
    inlineStylesheets: 'always', // no extra CSS request on first paint
  },
});
